clean_output:
:param kwargs: additional arguments to subprocess.check_output()
    :return: output of the command
    """

    # do not use logger, it is not initialized yet
    # print(f'running: {cmd}')

    if log_output:
        log_cmd = ' '.join(cmd)
        logger.debug(log_cmd)
    try:
        if return_output:
            output = subprocess.check_output(cmd, stderr=subprocess.STDOUT, **kwargs)
            if log_output:
                logger.debug(output.decode('utf-8'))
            return output
        else:
            subprocess.check_call(cmd, **kwargs)
    except subprocess.CalledProcessError as e:
        if ignore_status:
            logger.warning(f'{e.returncode} {e.cmd}')
            if log_output:
                logger.warning(e.output)
            return
        raise
